package com.example.starter.web.dto;

import com.example.starter.domain.ComponentType;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.time.Instant;

/**
 * 入库请求：每袋成分血以唯一条码入库，初始状态为待检。
 *
 * @param barcode       唯一条码
 * @param componentType 成分类型
 * @param expiresAt     效期边界时刻(UTC)，该时刻(含)之前可放行
 */
public record IntakeRequest(
        @NotBlank String barcode,
        @NotNull ComponentType componentType,
        @NotNull Instant expiresAt) {
}

package com.example.starter.web.dto;

import com.example.starter.domain.TestResultCode;
import com.example.starter.domain.TestType;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.time.Instant;

/**
 * 检测结果回传请求。初检与复检独立回传，允许乱序。
 *
 * @param barcode    成分条码
 * @param testType   INITIAL 初检 / REPEAT 复检
 * @param result     PASS 合格 / FAIL 不合格
 * @param receivedAt 回传时刻(UTC)，为空时以服务端当前时刻为准
 */
public record TestResultRequest(
        @NotBlank String barcode,
        @NotNull TestType testType,
        @NotNull TestResultCode result,
        Instant receivedAt) {
}

package com.example.starter.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.time.Instant;

/**
 * 放行请求，携带 requestId、条码与放行时间窗，以 requestId 幂等。
 *
 * @param requestId   幂等键
 * @param barcode     成分条码
 * @param windowStart 放行时间窗起点(UTC，含)
 * @param windowEnd   放行时间窗终点(UTC，含)
 * @param requestTime 请求判定时刻(UTC)，为空时以服务端当前时刻为准（用于效期与时间窗判定）
 */
public record ReleaseRequest(
        @NotBlank String requestId,
        @NotBlank String barcode,
        @NotNull Instant windowStart,
        @NotNull Instant windowEnd,
        Instant requestTime) {
}

package com.example.starter.web.dto;

import com.example.starter.domain.BloodUnit;

import java.time.Instant;

/**
 * 库存单位视图，所有时刻均为 UTC。
 */
public record UnitResponse(
        String barcode,
        String componentType,
        String status,
        String initialResult,
        String repeatResult,
        Instant initialReceivedAt,
        Instant repeatReceivedAt,
        Instant expiresAt,
        Instant expiredAt,
        String scrapReason,
        int version) {

    public static UnitResponse from(BloodUnit unit) {
        return new UnitResponse(
                unit.getBarcode(),
                unit.getComponentType().name(),
                unit.getStatus().name(),
                unit.getInitialResult() == null ? null : unit.getInitialResult().name(),
                unit.getRepeatResult() == null ? null : unit.getRepeatResult().name(),
                unit.getInitialReceivedAt(),
                unit.getRepeatReceivedAt(),
                unit.getExpiresAt(),
                unit.getExpiredAt(),
                unit.getScrapReason(),
                unit.getVersion());
    }
}

package com.example.starter.web.dto;

import java.time.Instant;

/**
 * 放行结果。同键同参重放时 {@code replay=true}，原样返回首次结论；
 * 同键异参由服务端以 409 拒绝，不产生本结果。
 */
public record ReleaseResponse(
        String requestId,
        String barcode,
        String status,
        String rejectReason,
        String unitStatus,
        Instant issuedAt,
        boolean replay) {
}

package com.example.starter.web.dto;

/**
 * 统一错误响应体。
 */
public record ErrorResponse(String error, String message) {
}

